// Helper: send CSV response
function sendCSV(res, filename, headers, rows) {
  res.setHeader('Content-Type', 'text/csv; charset=utf-8')
  res.setHeader('Content-Disposition', `attachment; filename="${filename}"`)
  res.setHeader('X-Content-Type-Options', 'nosniff')

  // Escape CSV formula injection (=, +, -, @)
  const escapeCsvValue = (val) => {
    if (val === null || val === undefined) return ''
    const str = String(val)
    if (/^[=+\-@]/.test(str)) return `'${str}`
    return str
  }

  // BOM for Excel UTF-8 compatibility
  let csv = '\uFEFF'
  csv += headers.join(',') + '\n'
  for (const row of rows) {
    csv += row.map(cell => {
      const escaped = escapeCsvValue(cell)
      return escaped.includes(',') || escaped.includes('"') || escaped.includes('\n')
        ? `"${escaped.replace(/"/g, '""')}"`
        : escaped
    }).join(',') + '\n'
  }
  res.send(csv)
}

// Helper: send Excel response
async function sendExcel(res, filename, sheetName, headers, rows) {
  const workbook = new ExcelJS.Workbook()
  const sheet = workbook.addWorksheet(sheetName)

  sheet.columns = headers.map((h, i) => ({
    header: h,
    key: `col${i}`,
    width: Math.max(h.length + 5, 15)
  }))

  // Style header row
  sheet.getRow(1).font = { bold: true }
  sheet.getRow(1).fill = {
    type: 'pattern',
    pattern: 'solid',
    fgColor: { argb: 'FF4472C4' }
  }
  sheet.getRow(1).font = { bold: true, color: { argb: 'FFFFFFFF' } }

  for (const row of rows) {
    const obj = {}
    headers.forEach((_, i) => { obj[`col${i}`] = row[i] })
    sheet.addRow(obj)
  }

  res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
  res.setHeader('Content-Disposition', `attachment; filename="${filename}"`)
  await workbook.xlsx.write(res)
  res.end()
}

