    const existing = await prisma.score.findFirst({
      where: { id: req.params.id, tenantId: req.tenantId }
    })
    if (!existing) throw new AppError('Score not found', 404, 'NOT_FOUND')

    await prisma.score.delete({ where: { id: req.params.id } })
