        classes: {
          include: { _count: { select: { students: true } } }
        }
      },
      orderBy: { level: 'asc' }
    })

    // Recent activity
    const recentLogs = await prisma.activityLog.findMany({
      where: { tenantId: schoolId },
      orderBy: { createdAt: 'desc' },
      take: 20
    })

    // Score stats
    const scoreStats = await prisma.score.aggregate({
      where: { tenantId: schoolId },
      _avg: { value: true },
      _min: { value: true },
      _max: { value: true },
      _count: true
    })

    res.json({
      data: {
        tenant,
        usersByRole,
        grades,
        recentLogs,
        scoreStats
      }
    })
  } catch (error) {
    next(error)
  }
})

