import { test, expect, APIRequestContext } from '@playwright/test';
import { createAuthContext } from '../helpers/api-client';

let superAdminCtx: APIRequestContext;
let staffCtx: APIRequestContext;
let teacherCtx: APIRequestContext;

test.beforeAll(async () => {
  superAdminCtx = await createAuthContext('SUPER_ADMIN');
  staffCtx = await createAuthContext('STAFF');
  teacherCtx = await createAuthContext('TEACHER');
});

test.afterAll(async () => {
  await superAdminCtx.dispose();
  await staffCtx.dispose();
  await teacherCtx.dispose();
});

test.describe('Scores', () => {
  let classId: string;
  let subjectId: string;
  let semesterId: string;
  let studentId: string;
  let scoreComponentId: string;

  test.beforeAll(async () => {
    // Get required IDs from seed data
    const classesRes = await superAdminCtx.get('/api/classes');
    const classesBody = await classesRes.json();
    const classes = classesBody.data;
    classId = classes[0]?.id;

    const subjectsRes = await superAdminCtx.get('/api/subjects');
    const subjectsBody = await subjectsRes.json();
    const subjects = subjectsBody.data;
    subjectId = subjects[0]?.id;

    // Get score components for the subject
    const componentsRes = await superAdminCtx.get(`/api/score-components?subjectId=${subjectId}`);
    if (componentsRes.ok()) {
      const componentsBody = await componentsRes.json();
      const components = componentsBody.data;
      scoreComponentId = components?.[0]?.id;
    }

    // Get students from a class
    const studentsRes = await superAdminCtx.get(`/api/students?classId=${classId}&limit=1`);
    if (studentsRes.ok()) {
      const studentsBody = await studentsRes.json();
      studentId = studentsBody.data?.[0]?.id;
    }

    // Get the active semester
    const academicYearsRes = await superAdminCtx.get('/api/academic-years');
    if (academicYearsRes.ok()) {
      const ayBody = await academicYearsRes.json();
      const years = ayBody.data;
      if (years?.[0]?.semesters) {
        semesterId = years[0].semesters[0]?.id;
      }
    }
  });

  test.describe('Class Score Sheet', () => {
    test('get class score sheet', async () => {
      if (!classId || !subjectId || !semesterId) {
        test.skip();
        return;
      }

      const response = await superAdminCtx.get(
        `/api/scores/class/${classId}?subjectId=${subjectId}&semesterId=${semesterId}`
      );
      expect(response.status()).toBe(200);

      const body = await response.json();
      expect(body).toBeTruthy();
    });

    test('class score sheet without required params returns 400', async () => {
      if (!classId) {
        test.skip();
        return;
      }

      const response = await superAdminCtx.get(`/api/scores/class/${classId}`);
      expect(response.status()).toBe(400);
    });
  });

  test.describe('Student Scores', () => {
    test('get student scores', async () => {
      if (!studentId) {
        test.skip();
        return;
      }

      const response = await superAdminCtx.get(`/api/scores/student/${studentId}`);
      expect(response.status()).toBe(200);
    });
  });

  test.describe('Upsert Score', () => {
    test('STAFF can upsert a single score', async () => {
      if (!studentId || !scoreComponentId || !semesterId) {
        test.skip();
        return;
      }

      const response = await staffCtx.post('/api/scores', {
        data: {
          studentId,
          scoreComponentId,
          semesterId,
          value: 8.5,
        },
      });
      expect([200, 201]).toContain(response.status());
    });

    test('upsert score with invalid value returns 400', async () => {
      if (!studentId || !scoreComponentId || !semesterId) {
        test.skip();
        return;
      }

      const response = await staffCtx.post('/api/scores', {
        data: {
          studentId,
          scoreComponentId,
          semesterId,
          value: 15, // Max is 10
        },
      });
      expect(response.status()).toBe(400);
    });
  });

  test.describe('Batch Upsert', () => {
    test('TEACHER can batch upsert scores', async () => {
      if (!studentId || !scoreComponentId || !semesterId) {
        test.skip();
        return;
      }

      const response = await teacherCtx.post('/api/scores/batch', {
        data: {
          scores: [
            {
              studentId,
              scoreComponentId,
              semesterId,
              value: 7.0,
            },
          ],
        },
      });
      // May succeed or fail based on teacher assignment
      expect([200, 201, 403]).toContain(response.status());
    });
  });
});

import { test, expect, APIRequestContext } from '@playwright/test';
import { createAuthContext } from '../helpers/api-client';

let superAdminCtx: APIRequestContext;
let staffCtx: APIRequestContext;
let teacherCtx: APIRequestContext;
let parentCtx: APIRequestContext;

test.beforeAll(async () => {
  superAdminCtx = await createAuthContext('SUPER_ADMIN');
  staffCtx = await createAuthContext('STAFF');
  teacherCtx = await createAuthContext('TEACHER');
  parentCtx = await createAuthContext('PARENT');
});

test.afterAll(async () => {
  await superAdminCtx.dispose();
  await staffCtx.dispose();
  await teacherCtx.dispose();
  await parentCtx.dispose();
});

test.describe('RBAC - Role-Based Access Control', () => {
  test.describe('TEACHER restrictions', () => {
    test('TEACHER cannot create student', async () => {
      const response = await teacherCtx.post('/api/students', {
        data: {
          fullName: 'Unauthorized Student',
          gender: 'MALE',
          dateOfBirth: '2009-01-01',
        },
      });
      expect(response.status()).toBe(403);
    });

    test('TEACHER cannot delete student', async () => {
      const listRes = await superAdminCtx.get('/api/students?limit=1');
      const listBody = await listRes.json();
      const studentId = listBody.data?.[0]?.id;

      if (studentId) {
        const response = await teacherCtx.delete(`/api/students/${studentId}`);
        expect(response.status()).toBe(403);
      }
    });

    test('TEACHER cannot manage fees', async () => {
      const response = await teacherCtx.get('/api/fees');
      expect(response.status()).toBe(403);
    });

    test('TEACHER cannot update settings', async () => {
      const response = await teacherCtx.put('/api/settings', {
        data: { maxClassSize: 50 },
      });
      expect(response.status()).toBe(403);
    });

    test('TEACHER cannot manage users', async () => {
      const response = await teacherCtx.get('/api/users');
      expect(response.status()).toBe(403);
    });
  });

  test.describe('PARENT restrictions', () => {
    test('PARENT cannot list all students', async () => {
      const response = await parentCtx.get('/api/students');
      expect(response.status()).toBe(403);
    });

    test('PARENT cannot create class', async () => {
      const response = await parentCtx.post('/api/classes', {
        data: {
          name: 'Unauthorized Class',
          gradeId: 'fake-id',
          academicYear: '2024-2025',
        },
      });
      expect(response.status()).toBe(403);
    });

    test('PARENT cannot create subject', async () => {
      const response = await parentCtx.post('/api/subjects', {
        data: { name: 'Unauth Subject', code: 'UA' },
      });
      expect(response.status()).toBe(403);
    });

    test('PARENT cannot manage fees', async () => {
      const response = await parentCtx.post('/api/fees', {
        data: {
          name: 'Unauth Fee',
          amount: 100,
          category: 'TUITION',
        },
      });
      expect(response.status()).toBe(403);
    });

    test('PARENT cannot update settings', async () => {
      const response = await parentCtx.put('/api/settings', {
        data: { passScore: 1 },
      });
      expect(response.status()).toBe(403);
    });
  });

  test.describe('STAFF restrictions', () => {
    test('STAFF cannot delete student', async () => {
      const listRes = await staffCtx.get('/api/students?limit=1');
      const listBody = await listRes.json();
      const studentId = listBody.data?.[0]?.id;

      if (studentId) {
        const response = await staffCtx.delete(`/api/students/${studentId}`);
        expect(response.status()).toBe(403);
      }
    });

    test('STAFF cannot update settings', async () => {
      const response = await staffCtx.put('/api/settings', {
        data: { maxClassSize: 50 },
      });
      expect(response.status()).toBe(403);
    });
  });

  test.describe('Unauthenticated access', () => {
    test('unauthenticated user cannot access protected routes', async ({ request }) => {
      const endpoints = [
        '/api/students',
        '/api/classes',
        '/api/subjects',
        '/api/scores/class/fake-id',
        '/api/fees',
        '/api/settings',
        '/api/reports/dashboard',
        '/api/users',
      ];

      for (const endpoint of endpoints) {
        const response = await request.get(endpoint);
        expect(response.status()).toBe(401);
      }
    });
  });
});

