    if (ayRes.ok()) {
      const ayBody = await ayRes.json();
      const years = ayBody.data;
      semesterId = years?.[0]?.semesters?.[0]?.id;
    }

    if (!scoreComponentId || !semesterId || students.length === 0) {
      test.skip();
      return;
    }

