      superAdminCtx.get(`/api/reports/semester-summary?semesterId=${semesterId}`)
    );

    console.log(`  Semester summary report: ${duration}ms`);
    expect(response.status()).toBe(200);
    expect(duration).toBeLessThan(3000);
  });
});

